#!/bin/sh
# Generated by FWShift: a Google Cloud network firewall policy, created with gcloud. Read the report first: what is
# not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE                              prints the commands; needs no access to Google Cloud
#   GCLOUD_OPTS='--project my-project' sh THIS_FILE     creates the policy and its rules
#
# The policy is associated with no network: nothing changes for any traffic until you associate it:
#   gcloud compute network-firewall-policies associations create --firewall-policy fwshift --network NETWORK --global-firewall-policy
# It decides every connection of that network. Set the network's enforcement order to BEFORE_CLASSIC_FIREWALL, or
# the VPC firewall rules of the network decide first. A policy of the same name stops the script before anything is
# created; a command gcloud refuses stops it where it is (delete the policy and run it again).
set -u
DRY_RUN="${DRY_RUN:-}"
GCLOUD_OPTS="${GCLOUD_OPTS:-}"
POLICY=fwshift
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
run() {
  if [ -n "$DRY_RUN" ]; then printf 'gcloud' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; return 0; fi
  gcloud "$@" $GCLOUD_OPTS --quiet >/dev/null || fail "gcloud $1 $2 $3 $4"
}
if [ -z "$DRY_RUN" ] && gcloud compute network-firewall-policies describe "$POLICY" --global $GCLOUD_OPTS >/dev/null 2>&1; then
  fail "a network firewall policy named $POLICY exists already; nothing was created"
fi

run compute network-firewall-policies create "$POLICY" --global '--description=Generated by FWShift; review the conversion report before associating it'

run compute network-firewall-policies rules create 1000 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=10.10.1.4/32 --layer4-configs=tcp:443 '--description=dnat-web/web-https (DNAT)'
run compute network-firewall-policies rules create 1010 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=10.10.1.4/32 --layer4-configs=tcp:443 '--description=dnat-web/web-https (DNAT)'
run compute network-firewall-policies rules create 1020 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=198.51.100.0/24 --dest-ip-ranges=10.10.1.5/32 --layer4-configs=tcp:22 '--description=dnat-web/ssh-admin (DNAT)'
run compute network-firewall-policies rules create 1030 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=198.51.100.0/24 --dest-ip-ranges=10.10.1.5/32 --layer4-configs=tcp:22 '--description=dnat-web/ssh-admin (DNAT)'
run compute network-firewall-policies rules create 1040 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=tcp:23 --description=base-deny/deny-telnet
run compute network-firewall-policies rules create 1050 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=tcp:23 --description=base-deny/deny-telnet
run compute network-firewall-policies rules create 1060 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=10.10.0.0/16 --dest-ip-ranges=10.10.8.8/31 --layer4-configs=tcp:53,udp:53 --description=base-allow-dns/dns-out
run compute network-firewall-policies rules create 1070 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=10.10.0.0/16 --dest-ip-ranges=10.10.8.8/31 --layer4-configs=tcp:53,udp:53 --description=base-allow-dns/dns-out
run compute network-firewall-policies rules create 1080 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=10.10.4.0/24 --dest-ip-ranges=192.0.2.0/24 --layer4-configs=all --description=net-partner/every-protocol-to-partner
run compute network-firewall-policies rules create 1090 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=10.10.4.0/24 --dest-ip-ranges=192.0.2.0/24 --layer4-configs=all --description=net-partner/every-protocol-to-partner
run compute network-firewall-policies rules create 1100 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=10.10.0.0/16 --dest-ip-ranges=10.10.8.53/32 --layer4-configs=tcp:53,udp:53 --description=net-partner/dns-any-protocol
run compute network-firewall-policies rules create 1110 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=10.10.0.0/16 --dest-ip-ranges=10.10.8.53/32 --layer4-configs=tcp:53,udp:53 --description=net-partner/dns-any-protocol
run compute network-firewall-policies rules create 1120 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=10.10.1.0/24 --dest-ip-ranges=10.10.2.0/24 --layer4-configs=tcp:1433 --description=net-allow-web/web-to-db
run compute network-firewall-policies rules create 1130 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=10.10.1.0/24 --dest-ip-ranges=10.10.2.0/24 --layer4-configs=tcp:1433 --description=net-allow-web/web-to-db
run compute network-firewall-policies rules create 1140 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=10.10.9.0/24 --dest-ip-ranges=10.10.0.0/16 --layer4-configs=icmp --description=net-allow-web/icmp-mgmt
run compute network-firewall-policies rules create 1150 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=10.10.9.0/24 --dest-ip-ranges=10.10.0.0/16 --layer4-configs=icmp --description=net-allow-web/icmp-mgmt
run compute network-firewall-policies rules create 1160 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=10.10.1.10/31,10.10.1.12/30,10.10.1.16/30,10.10.1.20/32 --dest-ip-ranges=10.10.3.0/24 --layer4-configs=tcp:8000-8080,tcp:9000 --description=net-allow-web/app-ports
run compute network-firewall-policies rules create 1170 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=10.10.1.10/31,10.10.1.12/30,10.10.1.16/30,10.10.1.20/32 --dest-ip-ranges=10.10.3.0/24 --layer4-configs=tcp:8000-8080,tcp:9000 --description=net-allow-web/app-ports
run compute network-firewall-policies rules create 1180 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=10.10.0.0/16 --dest-ip-ranges=10.10.0.0/16 --layer4-configs=all --description=net-deny-lateral/block-lateral
run compute network-firewall-policies rules create 1190 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=10.10.0.0/16 --dest-ip-ranges=10.10.0.0/16 --layer4-configs=all --description=net-deny-lateral/block-lateral
run compute network-firewall-policies rules create 1200 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1210 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1220 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1230 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all --description=fwshift-default-deny

# Not written:
#   net-partner/v6-ssh: not converted: IPv6 source address '2001:db8:10::/64', which Azure Firewall does not take
#   net-allow-web/ntp-out: host name object time.example.org: the rules are written with addresses
#   net-allow-web/storage: references 'Storage.WestEurope': dynamic address group, members are not known statically; the destination 'Storage.WestEurope' holds members only its platform knows; a rule of Google Cloud names addresses
#   net-allow-web/partner-sftp: references 'ipg-partners': dynamic address group, members are not known statically; the source 'ipg-partners' holds members only its platform knows; a rule of Google Cloud names addresses
#   app-out/allow-updates: not converted: an application rule matches by the name the client asks for (HTTP Host header, TLS SNI), not by address: target FQDNs *.example.com, updates.example.net; host name object *.example.com: the rules are written with addresses
#   app-out/allow-wsus: not converted: an application rule matches by the name the client asks for (HTTP Host header, TLS SNI), not by address: FQDN tags WindowsUpdate
#   app-deny/no-gambling: not converted: an application rule matches by the name the client asks for (HTTP Host header, TLS SNI), not by address: web categories Gambling

echo 'Done. Associate the policy with the network when you are ready; until then nothing changes.' >&2
